insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1230.svg', '1230-01-01', '1574-09-13', 'Dynastie hafside', 'Hafsid dynasty', 'Bannière des Hafsides, qui gouvernent Tunis du XIIIe siècle à la conquête ottomane de 1574.', 'Banner of the Hafsids, who ruled Tunis from the 13th century until the Ottoman conquest of 1574.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1831.svg', '1831-01-01', '1959-06-01', 'Beylicat de Tunis puis protectorat (1831-1959)', 'Beylik of Tunis, then protectorate (1831–1959)', 'Adopté par Hussein II bey après la bataille de Navarin (1827), où la flotte tunisienne n''avait pu être distinguée des autres : croissant et étoile rouges dans un disque blanc.', 'Adopted by Hussein II Bey after the Battle of Navarino (1827), where the Tunisian fleet could not be told apart from others: a red crescent and star in a white disc.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1959.svg', '1959-06-01', '1999-06-30', 'République tunisienne (1959-1999)', 'Tunisian Republic (1959–1999)', 'La Constitution de 1959 confirme le drapeau beylical ; ses proportions et son dessin sont normalisés par la loi de 1999.', 'The 1959 Constitution confirmed the beylical flag; its proportions and design were standardised by the 1999 law.');
